package com.sekai.app.waf;

import lombok.val;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.web.servlet.HandlerInterceptor;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.nio.file.AccessDeniedException;
import java.util.Optional;

@Configuration
@Order(Integer.MIN_VALUE)
public class FrogWaf implements HandlerInterceptor {
    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object obj) throws Exception {
        // Uri
        val query = request.getQueryString();
        if (query != null) {
            val v = getViolationByString(query);
            if (v.isPresent()) {
                throw new AccessDeniedException(String.format("Malicious input found: %s", v));
            }
        }
        return true;
    }

    public static Optional<WafViolation> getViolationByString(String userInput) {
        for (val c : AttackTypes.values()) {
            for (val m : c.getAttackStrings()) {
                if (userInput.contains(m)) {
                    return Optional.of(new WafViolation(c, m));
                }
            }
        }
        return Optional.empty();
    }

}

package com.sekai.app.controller.contact;

import lombok.val;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.ModelAndView;

import javax.servlet.http.HttpSession;
import javax.validation.Valid;
import java.util.ArrayList;

@RestController
class ContactController {

    private final static String CONTACTS = "contacts";

    @PostMapping("/addContact")
    ResponseEntity<String> addContact(HttpSession session, @Valid @RequestBody Contact contact) {
        if (session.getAttribute(CONTACTS) == null) {
            session.setAttribute(CONTACTS, new ArrayList<Contact>());
        }
        val contacts = (ArrayList<Contact>) session.getAttribute(CONTACTS);
        contacts.add(contact);
        return ResponseEntity.ok("contact added");
    }

    @GetMapping("/")
    ModelAndView index(HttpSession session) {
        if (session.getAttribute(CONTACTS) == null) {
            session.setAttribute(CONTACTS, new ArrayList<Contact>());
        }
        val modelAndView = new ModelAndView("index.html");
        val contacts = (ArrayList<Contact>) session.getAttribute(CONTACTS);
        modelAndView.addObject("contacts", contacts);
        return modelAndView;
    }

}

